/**
 * quizParser.ts
 * Zero-escape parser for interactive MCQs & quizzes generated by Dream It AI.
 * Handles LaTeX formulas cleanly without JSON escaping issues, and includes a
 * natural-Markdown MCQ fallback parser when the user explicitly requests a quiz.
 */

import { safeParseJSON } from "./json-repair";
import type { InteractiveQuizSpec, QuizQuestion } from "../app/components/AIInteractiveQuizCard";

export const QUIZ_TOKEN_START = "<!--DREAMIT_QUIZ_START-->";
export const QUIZ_TOKEN_END = "<!--DREAMIT_QUIZ_END-->";

export function encodeQuizToken(spec: InteractiveQuizSpec): string {
  return `${QUIZ_TOKEN_START}${JSON.stringify(spec)}${QUIZ_TOKEN_END}`;
}

/**
 * Strictly checks whether the user explicitly asked for MCQs or a quiz.
 * Normal explanations, summaries, notes, or PDF requests return false.
 */
export function isExplicitQuizRequest(prompt: string): boolean {
  if (!prompt) return false;
  const trimmed = prompt.trim();
  if (/^\/(?:quiz|mcq|mcqs)\b/i.test(trimmed)) return true;
  return /\b(?:mcqs?|quiz(?:zes)?|qiuz|multiple[\s-]*choice|practice\s+questions?|test\s+me|quiz\s+me)\b/i.test(
    trimmed
  );
}

/** Parse a single question chunk into a structured QuizQuestion */
function parseQuestionChunk(chunk: string): QuizQuestion | null {
  const lines = chunk
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean);
  if (lines.length < 3) return null;

  let questionLines: string[] = [];
  const options: Array<{ label: string; text: string }> = [];
  let answerRaw = "";
  let explanationLines: string[] = [];
  let mode: "question" | "option" | "explanation" = "question";

  for (const line of lines) {
    // Match Answer line: ANSWER: B / **Answer:** (B) / Correct Answer: C
    const ansMatch =
      /^(?:\*{0,2})(?:correct\s+)?(?:answer|ans)(?:\*{0,2})\s*[:\-]\s*(.+)$/i.exec(line);
    if (ansMatch) {
      answerRaw = ansMatch[1].trim();
      mode = "question";
      continue;
    }

    // Match Explanation line: EXPLANATION: ... / **Explanation:** ...
    const expMatch =
      /^(?:\*{0,2})(?:explanation|rationale|solution|reason|hint)(?:\*{0,2})\s*[:\-]\s*(.*)$/i.exec(
        line
      );
    if (expMatch) {
      if (expMatch[1].trim()) explanationLines.push(expMatch[1].trim());
      mode = "explanation";
      continue;
    }

    // Match Option line: A) ... / A. ... / (A) ... / - A) ... / **A)** ...
    const optMatch =
      /^(?:[-*]\s*)?(?:\*{0,2})\(?([A-E])\)?[.)]\s*(?:\*{0,2})\s*(.+)$/.exec(line);
    if (optMatch && (options.length > 0 || optMatch[1].toUpperCase() === "A")) {
      options.push({
        label: optMatch[1].toUpperCase(),
        text: optMatch[2].trim(),
      });
      mode = "option";
      continue;
    }

    if (mode === "explanation") {
      explanationLines.push(line);
    } else if (mode === "option" && options.length > 0) {
      // Continuation line of the previous option
      options[options.length - 1].text += " " + line;
    } else {
      // Question stem line (strip leading Q: / Q1. / 1. / **Question 1:**)
      const cleanedQ = line
        .replace(/^(?:\*{0,2})(?:Question\s*\d+|Q\d*|#?\d+)[.):\s-]+(?:\*{0,2})\s*/i, "")
        .trim();
      if (cleanedQ) questionLines.push(cleanedQ);
    }
  }

  const question = questionLines.join(" ").trim();
  if (!question || options.length < 2) return null;

  // Determine correct option index from answerRaw (e.g. "D", "B) Osmotic pressure", "(C)")
  let correctIndex = 0;
  const letterMatch = /\b([A-E])\b/i.exec(answerRaw) || /^\(?([A-E])\)?[.):]?/i.exec(answerRaw);
  if (letterMatch) {
    const targetLabel = letterMatch[1].toUpperCase();
    const idx = options.findIndex((o) => o.label === targetLabel);
    if (idx !== -1) correctIndex = idx;
  } else if (answerRaw) {
    // Match by option text substring
    const normAns = answerRaw.toLowerCase();
    const idx = options.findIndex((o) => normAns.includes(o.text.toLowerCase()));
    if (idx !== -1) correctIndex = idx;
  }

  return {
    question,
    options,
    correctIndex,
    explanation: explanationLines.join(" ").trim() || undefined,
  };
}

/**
 * Parses a fenced ```interactive_quiz ... ``` block (zero-escape Markdown format or JSON).
 */
export function parseInteractiveQuizBlock(
  rawText: string,
  defaultSubject?: string
): { spec: InteractiveQuizSpec | null; remainingText: string } {
  const fenceMarker = "```interactive_quiz";
  const fenceIdx = rawText.indexOf(fenceMarker);
  if (fenceIdx === -1) return { spec: null, remainingText: rawText };

  const before = rawText.slice(0, fenceIdx).trim();
  let body = rawText.slice(fenceIdx + fenceMarker.length).replace(/^\r?\n/, "");
  const lastFenceIdx = body.lastIndexOf("\n```");
  let after = "";
  if (lastFenceIdx !== -1) {
    after = body.slice(lastFenceIdx + 4).trim();
    body = body.slice(0, lastFenceIdx).trim();
  } else if (body.trimEnd().endsWith("```")) {
    body = body.trimEnd().slice(0, -3).trim();
  }

  const remainingText = [before, after].filter(Boolean).join("\n\n").trim();

  // Optional JSON fallback if model emitted JSON inside ```interactive_quiz
  if (body.trimStart().startsWith("{")) {
    const parsed = safeParseJSON<any>(body, null);
    if (parsed && Array.isArray(parsed.questions) && parsed.questions.length > 0) {
      const normalized: QuizQuestion[] = parsed.questions
        .map((q: any) => {
          const opts = Array.isArray(q.options)
            ? q.options.map((o: any, i: number) =>
                typeof o === "string"
                  ? {
                      label: String.fromCharCode(65 + i),
                      text: o.replace(/^\(?[A-E]\)?[.)]\s*/i, "").trim(),
                    }
                  : { label: o.label || String.fromCharCode(65 + i), text: String(o.text || "") }
              )
            : [];
          let cIdx = typeof q.correctIndex === "number" ? q.correctIndex : 0;
          if (typeof q.answer === "string") {
            const lm = /([A-E])/i.exec(q.answer);
            if (lm) {
              const found = opts.findIndex((o: any) => o.label === lm[1].toUpperCase());
              if (found !== -1) cIdx = found;
            }
          }
          return {
            question: String(q.question || q.q || "").trim(),
            options: opts,
            correctIndex: cIdx,
            explanation: q.explanation ? String(q.explanation).trim() : undefined,
          };
        })
        .filter((q: QuizQuestion) => q.question && q.options.length >= 2);

      if (normalized.length > 0) {
        return {
          spec: {
            title: String(parsed.title || "Interactive Practice Quiz").trim(),
            subject: parsed.subject || defaultSubject,
            difficulty: parsed.difficulty || "Medium",
            questions: normalized,
          },
          remainingText,
        };
      }
    }
  }

  // Zero-escape frontmatter + --- separated Q blocks
  let title = "Interactive Practice Quiz";
  let subject: string | undefined = defaultSubject;
  let difficulty = "Medium";

  const chunks = body.split(/\n---[ \t]*\n/);
  const questionChunks: string[] = [];

  chunks.forEach((chunk, idx) => {
    const trimmed = chunk.trim();
    if (!trimmed) return;
    if (idx === 0 && !/^(?:Q\d*\s*[:.]|Question\s*\d+|1\.)/i.test(trimmed)) {
      // Parse metadata header lines
      let hasMeta = false;
      for (const line of trimmed.split("\n")) {
        const kv = /^([a-zA-Z_]+)\s*:\s*(.+)$/.exec(line.trim());
        if (!kv) continue;
        const k = kv[1].toLowerCase();
        const v = kv[2].replace(/^["']|["']$/g, "").trim();
        if (k === "title" && v) {
          title = v;
          hasMeta = true;
        } else if (k === "subject" && v) {
          subject = v;
          hasMeta = true;
        } else if (k === "difficulty" && v) {
          difficulty = v;
          hasMeta = true;
        }
      }
      if (!hasMeta) questionChunks.push(trimmed);
    } else {
      questionChunks.push(trimmed);
    }
  });

  // If the AI didn't use --- between questions, split by Q: / Q1: markers
  const finalChunks =
    questionChunks.length === 1
      ? questionChunks[0].split(/\n(?=(?:\*{0,2})(?:Q\d*\s*[:.]|Question\s+\d+\s*[:.]))/i)
      : questionChunks;

  const questions = finalChunks
    .map(parseQuestionChunk)
    .filter((q): q is QuizQuestion => q !== null);

  if (questions.length === 0) {
    return { spec: null, remainingText: rawText };
  }

  return {
    spec: { title, subject, difficulty, questions },
    remainingText,
  };
}

/**
 * Fallback parser for natural Markdown MCQs when the user explicitly asked for a quiz
 * and the AI outputted numbered questions without the ```interactive_quiz fence.
 */
export function parseNaturalMarkdownMcqs(
  rawText: string,
  defaultTitle = "Practice Quiz",
  defaultSubject?: string
): { spec: InteractiveQuizSpec | null; remainingText: string } {
  // Check if there is a trailing Answer Key section (e.g. "### Answer Key\n1. B\n2. D")
  const answerKeyMap: Record<number, string> = {};
  let mainText = rawText;
  const keySectionMatch = /\n(?:#{1,4}\s*|\*{2})(?:Answer\s*Key|Answers|Solutions)\*{0,2}\s*:?\s*\n([\s\S]+)$/i.exec(
    rawText
  );
  if (keySectionMatch) {
    const keyLines = keySectionMatch[1].split("\n");
    for (const kl of keyLines) {
      const m = /^(?:[-*]\s*)?(?:Q\s*)?(\d+)[.):\s-]+\*{0,2}\(?([A-E])\)?/i.exec(kl.trim());
      if (m) answerKeyMap[Number(m[1])] = m[2].toUpperCase();
    }
    if (Object.keys(answerKeyMap).length >= 2) {
      mainText = rawText.slice(0, keySectionMatch.index).trim();
    }
  }

  // Split by numbered question starts: "1. ..." or "**1.** ..." or "### Q1."
  const parts = mainText.split(
    /\n(?=(?:#{1,4}\s*)?(?:\*{0,2})(?:Q(?:uestion)?\s*\d+|\d+)[.):]\s+)/i
  );

  const questions: QuizQuestion[] = [];
  const introParts: string[] = [];

  parts.forEach((part, idx) => {
    const parsed = parseQuestionChunk(part);
    if (parsed) {
      const qNum = questions.length + 1;
      if (answerKeyMap[qNum]) {
        const keyIdx = parsed.options.findIndex((o) => o.label === answerKeyMap[qNum]);
        if (keyIdx !== -1) parsed.correctIndex = keyIdx;
      }
      questions.push(parsed);
    } else if (idx === 0) {
      introParts.push(part.trim());
    }
  });

  if (questions.length < 2) {
    return { spec: null, remainingText: rawText };
  }

  const headingMatch = mainText.match(/^#+\s*(.+)$/m);
  const title = headingMatch
    ? headingMatch[1].replace(/[*#`]/g, "").trim()
    : defaultTitle;

  return {
    spec: {
      title,
      subject: defaultSubject,
      difficulty: "Medium",
      questions,
    },
    remainingText: introParts.join("\n\n").replace(/^#+\s*.+$/m, "").trim(),
  };
}

/** Extract finalized or raw interactive quiz from a chat message */
export function extractQuizFromContent(
  content: string
): { spec: InteractiveQuizSpec | null; remainingText: string } {
  const startIdx = content.indexOf(QUIZ_TOKEN_START);
  const endIdx = content.indexOf(QUIZ_TOKEN_END);
  if (startIdx !== -1 && endIdx > startIdx) {
    const rawJson = content.slice(startIdx + QUIZ_TOKEN_START.length, endIdx);
    const remainingText = (
      content.slice(0, startIdx) + content.slice(endIdx + QUIZ_TOKEN_END.length)
    ).trim();
    try {
      const parsed = safeParseJSON<InteractiveQuizSpec | null>(rawJson, null);
      if (parsed && Array.isArray(parsed.questions) && parsed.questions.length > 0) {
        return { spec: parsed, remainingText };
      }
    } catch {
      // Fallback
    }
  }

  // Auto-recover any saved raw ```interactive_quiz blocks
  if (content.includes("```interactive_quiz")) {
    return parseInteractiveQuizBlock(content);
  }

  return { spec: null, remainingText: content };
}
